export function normalizePercent(text, subject) {
  let out = ''
  let index = 0
  while (index < text.length) {
    const character = text[index]
    if (character === '%') {
      const triplet = text.slice(index, index + 3)
      if (!TRIPLET.test(triplet)) throw new UriError(`${subject} has a truncated percent-encoding`)
      const upper = triplet.toUpperCase()
      const decoded = String.fromCharCode(parseInt(upper.slice(1), 16))
      out += UNRESERVED.test(decoded) ? decoded : upper
      index += 3
    } else {
      out += character
      index += 1
    }
  }
  return out
}

